const qwenResp = $('qwen3.5:4b').first().json;
const qwenText = qwenResp.message?.content || qwenResp.choices?.[0]?.message?.content || '';

const filtrItems = $('Фильтр NBA и ВТБ').all();

const numsLine = qwenText.match(/(?:лучшие матчи|лучший матч)\s*[:№]?\s*([\d\s,.;и]+)/i);
let nums = numsLine ? (numsLine[1].match(/\d+/g) || []).map(n => parseInt(n, 10)) : [];
nums = [...new Set(nums)].filter(n => n >= 1 && n <= filtrItems.length).slice(0, 3);

let selectedBy = 'qwen';
if (nums.length === 0) {
  selectedBy = 'fallback';
  nums = [1, 2, 3].filter(n => n <= filtrItems.length);
}

if (nums.length === 0) {
  return [{ json: { error: 'Не удалось отобрать матчи', qwenText: qwenText.slice(0, 500) } }];
}

return nums.map(n => ({
  json: {
    gameId: filtrItems[n - 1].json.gameId,
    matchLabel: filtrItems[n - 1].json.homeTeam + ' - ' + filtrItems[n - 1].json.awayTeam,
    selectedBy
  }
}));

const items = $input.all();

function fmtOdds(market) {
  const choices = (market.choices || [])
    .map(c => c.name + '@' + (c.decimal ?? c.value ?? '?'))
    .join(', ');
  return market.name + ' (' + (market.group || 'общий') + '): ' + choices;
}

function allMarketsSection(oddsBase, oddsBk) {
  const parts = [];
  if (Array.isArray(oddsBase) && oddsBase.length) {
    parts.push('ОСНОВНЫЕ РЫНКИ:');
    parts.push(oddsBase.map(fmtOdds).join('\n'));
  }
  if (oddsBk && typeof oddsBk === 'object') {
    for (const [bookmaker, data] of Object.entries(oddsBk)) {
      if (data && Array.isArray(data.markets) && data.markets.length) {
        parts.push('--- БУКМЕКЕР ' + bookmaker.toUpperCase() + ' ---');
        parts.push(data.markets.map(fmtOdds).join('\n'));
      }
    }
  }
  return parts.join('\n') || 'Нет данных';
}

const MAX_BLOCK = 9000;
const blocks = [];
for (const item of items) {
  const d = item.json;
  if (!d || d.error || !d.homeTeam) continue;

  const pregame = d.pregame || {};
  const missingH = d.homeTeam.lineup?.missingPlayers || [];
  const missingA = d.awayTeam.lineup?.missingPlayers || [];

  let block = [
    '=== МАТЧ: ' + (d.homeTeam.name || '?') + ' - ' + (d.awayTeam.name || '?') + ' (' + (d.tournament?.name || '?') + ') ===',
    'ВСЕ ДОСТУПНЫЕ РЫНКИ:',
    allMarketsSection(d.oddsBase || [], d.oddsBk || {}),
    'ФОРМА ХОЗЯЕВ: ' + JSON.stringify(pregame.form?.homeTeam || pregame.form || {}).slice(0, 300),
    'ФОРМА ГОСТЕЙ: ' + JSON.stringify(pregame.form?.awayTeam || {}).slice(0, 300),
    'ОЧНЫЕ ВСТРЕЧИ: ' + JSON.stringify(pregame.h2h || {}).slice(0, 250),
    'СЕРИИ: ' + JSON.stringify(pregame.teamStreaks || {}).slice(0, 250),
    'ТРАВМЫ ХОЗЯЕВ: ' + (missingH.map(p => p.player?.name).join(', ') || 'нет'),
    'ТРАВМЫ ГОСТЕЙ: ' + (missingA.map(p => p.player?.name).join(', ') || 'нет')
  ].join('\n');

  if (block.length > MAX_BLOCK) block = block.slice(0, MAX_BLOCK) + '\n... (рынки обрезаны по лимиту)';
  blocks.push(block);
}

if (blocks.length === 0) {
  return [{ json: { error: 'Нет данных по выбранным матчам' } }];
}

const prompt = [
  'Данные по ' + blocks.length + ' матчам. По каждому матчу доступна ПОЛНАЯ линия: базовые рынки и рынки нескольких букмекеров (исходы, тоталы, форы, индивидуальные тоталы, комбо исход+тотал и т.д.).',
  '',
  blocks.join('\n\n'),
  '',
  'ТВОЯ ЗАДАЧА:',
  'Для КАЖДОГО матча выбери ОДИН самый перспективный рынок из доступных в линии — не ограничивайся исходом: рассмотри тоталы, форы, индивидуальные тоталы команд, комбинированные рынки (исход+тотал).',
  'Требования к каждой ставке:',
  '- кэф строго от 1.30 до 1.90 (не бери явных фаворитов с кэфом ниже 1.30);',
  '- используй ТОЛЬКО рынки и значения, реально присутствующие в предоставленных данных;',
  '- учитывай форму, травмы и очные встречи;',
  '  - ЗАПРЕЩЕНЫ лотерейные рынки, у которых исход почти случаен и не выводится из статистики: чет/нечет, точный счет, точное количество очков, интервалы очков (например 1-я четверть: очки 20-25), кто наберет очко/первый гол первым, мультикол-во, мультисчет, последняя/следующая четверть по номеру. ЗАПРЕЩЕНЫ любые рынки с кэфом ниже 1.30.',
  '',
  'ФОРМАТ ОТВЕТА — строго одна строка на матч, без нумерации, без текста до и после:',
  'Матч: [Команда1] - [Команда2] | Рынок: [название рынка] | Прогноз: [значение] | Кэф: [число] | Уверенность: [X]/10',
  '',
  'Если по матчу данных недостаточно — пропусти этот матч. Отвечай СТРОГО на русском языке.'
].join('\n');

return [{ json: { raw_data_for_deepseek: prompt, matches_count: blocks.length } }];

