const raw = $input.first().json;
const text = raw.choices?.[0]?.message?.content || raw.message?.content || raw.output || raw.text || '';

const pickRe = /Матч:\s*([^-|]+?)\s*-\s*([^|]+?)\s*\|\s*Рынок:\s*([^|]+?)\s*\|\s*Прогноз:\s*([^|]+?)\s*\|\s*Кэф:\s*([\d]+(?:[.,]\d+)?)\s*\|\s*Уверенность:\s*(\d{1,2})/g;

const picks = [];
let m;
while ((m = pickRe.exec(text)) !== null) {
  const k = parseFloat(String(m[5]).replace(',', '.'));
  if (!Number.isFinite(k) || k < 1.01) continue;
  picks.push({
    match: m[1].trim() + ' - ' + m[2].trim(),
    market: m[3].trim(),
    forecast: m[4].trim(),
    odds: k,
    confidence: parseInt(m[6], 10)
  });
}

if (picks.length === 0) {
  return [{ json: { error: 'Не удалось разобрать ставки из ответа', raw: text.slice(0, 600) } }];
}

const lotteryRe = /чет|нечет|нечёт|чёт|точн(ый|ое)\s+(счет|счёт|кол)|мультисчет|мультисчёт|мультикол|интервал|кто\s+(забьет|наберет|подаст)|перв(ый|ая)\s+(гол|очко|карточка|угловой)|последн(ий|яя)\s+(гол|очко|карточка|угловой)|следующ(ий|ая)\s+гол|1-й гол|очко\s+в\s+пуст/i;
const cleanPicks = picks.filter(p => !lotteryRe.test(p.market) && !lotteryRe.test(p.forecast));
const dropped = picks.length - cleanPicks.length;
picks.length = 0;
picks.push(...cleanPicks);

if (picks.length === 0) {
  return [{ json: { error: 'Все ставки отброшены фильтром лотерейных рынков', raw: text.slice(0, 600) } }];
}

const combos = [];
for (let i = 0; i < picks.length; i++) {
  for (let j = i + 1; j < picks.length; j++) {
    const pair = [picks[i], picks[j]];
    combos.push({ legs: pair, total: pair.reduce((acc, p) => acc * p.odds, 1) });
    for (let t = j + 1; t < picks.length; t++) {
      const triple = [picks[i], picks[j], picks[t]];
      combos.push({ legs: triple, total: triple.reduce((acc, p) => acc * p.odds, 1) });
    }
  }
}

const valid = combos.filter(c => c.total > 3.0).sort((a, b) => b.total - a.total);
const best = valid[0] || null;
const bestSingle = [...picks].sort((a, b) => (b.odds * b.confidence) - (a.odds * a.confidence))[0];

return [{
  json: {
    express_found: !!best,
    express_total_odds: best ? Math.round(best.total * 100) / 100 : null,
    express_legs: best ? best.legs : [],
    singles: picks,
    dropped_lottery: dropped,
    fallback_single: best ? null : bestSingle
  }
}];

const r = $input.first().json;

if (r.error) {
  return [{ json: { 'СТАТУС': '⚠️ ' + r.error, 'ДЕТАЛИ': r.raw || '' } }];
}

function legText(l, i) {
  return (i + 1) + ') ' + l.match + ' | ' + l.market + ' | Прогноз: ' + l.forecast + ' | Кэф: ' + l.odds + ' | Уверенность: ' + l.confidence + '/10';
}

let out;
if (r.express_found) {
  out = '🎯 ЭКСПРЕСС (итоговый кэф ' + r.express_total_odds + '):\n'
    + r.express_legs.map(legText).join('\n');
} else if (r.fallback_single) {
  out = '⚠️ Экспресс с кэфом > 3 не собрался. Лучшая одиночная ставка:\n' + legText(r.fallback_single, 0);
} else {
  out = '⚠️ Подходящих ставок не найдено.';
}

out += '\n\nВсе одиночные варианты:\n' + r.singles.map(legText).join('\n');

return [{ json: { 'СТАТУС': '✅ Готово', 'ПРОГНОЗ': out } }];
